import re

def solve(env, goal):
    def parse_obs(s):
        objs = []
        recs = []
        # "You arrive at sofa 1. On the sofa 1, you see ..."
        for name, num in re.findall(r"\b([a-zA-Z][a-zA-Z0-9_]*?) ([0-9]+)\b", s):
            if name in ("shelf", "sofa", "armchair", "coffeetable", "garbagecan", "tvstand",
                        "table", "counter", "cabinet", "drawer", "bed", "desk", "chair",
                        "fridge", "microwave", "sink", "toilet", "bathtub", "dresser",
                        "safe", "box", "cart", "shelves", "receptacle", "storage"):
                recs.append(f"{name} {num}")
            else:
                objs.append((name, num))
        return objs, recs

    def parse_goal(g):
        g = g.strip().lower().rstrip(".")
        m = re.search(r"\b(?:in|on|to)\s+(?:the\s+)?([a-zA-Z][a-zA-Z0-9_]*(?:\s+[0-9]+)?)", g)
        target = None
        if m:
            target = m.group(1).strip()
        else:
            # maybe "in sofa" without number
            m = re.search(r"\b(?:in|on|to)\s+(?:the\s+)?([a-zA-Z][a-zA-Z0-9_]*)", g)
            if m:
                target = m.group(1).strip()
        wanted = []
        numwords = {"one":1,"two":2,"three":3,"four":4,"five":5,"six":6,"seven":7,"eight":8,"nine":9,"ten":10}
        for cnt_str, obj in re.findall(r"\b(one|two|three|four|five|six|seven|eight|nine|ten|\d+)\s+([a-zA-Z][a-zA-Z0-9_]*)", g):
            cnt = numwords.get(cnt_str)
            if cnt is None:
                try:
                    cnt = int(cnt_str)
                except:
                    cnt = 1
            wanted.append((obj, cnt))
        return target, wanted

    def norm(s):
        return s.strip().lower().rstrip(".")

    target, wanted = parse_goal(goal)
    if not wanted:
        # fallback: maybe "put the apple in fridge" -> wanted apple 1
        pass

    obs = env.observation
    objs_here, recs_here = parse_obs(obs)
    cur_loc = None
    m = re.search(r"You arrive at ([^.,]+)", obs)
    if m:
        cur_loc = m.group(1).strip()
    else:
        m = re.search(r"You are facing (?:the )?([^.,]+)", obs)
        if m:
            cur_loc = m.group(1).strip()

    held = []
    steps = 0

    def step(cmd):
        nonlocal steps, obs, objs_here, recs_here, cur_loc
        if steps >= 50:
            return None
        steps += 1
        fb = env.step(cmd)
        obs = fb
        objs_here, recs_here = parse_obs(obs)
        m = re.search(r"You arrive at ([^.,]+)", obs)
        if m:
            cur_loc = m.group(1).strip()
        m = re.search(r"You pick up the ([^.,]+)", obs)
        if m:
            held.append(m.group(1).strip())
        m = re.search(r"You move the ([^.,]+) to", obs)
        if m:
            name = m.group(1).strip()
            for i, h in enumerate(held):
                if h == name:
                    held.pop(i)
                    break
        return fb

    def go(loc):
        if loc is None:
            return
        if norm(cur_loc or "") == norm(loc):
            return
        step(f"go to {loc}")

    def look():
        step("look")

    def count_held(base):
        return sum(1 for h in held if h == base or h.startswith(base + " "))

    def free_held(base):
        for h in held:
            if h == base or h.startswith(base + " "):
                return h
        return None

    # initial look
    look()

    # gather receptacles from initial observation plus target
    initial_recs = list(recs_here)
    if target and norm(target) not in [norm(r) for r in initial_recs]:
        initial_recs.append(target)

    wanted_bases = [w[0] for w in wanted]
    needed = {}
    for b, n in wanted:
        needed[b] = needed.get(b, 0) + n

    # Phase 1: visit receptacles (excluding target) and pick wanted objects
    for rec in initial_recs:
        if norm(rec) == norm(target):
            continue
        go(rec)
        look()
        for base, num in wanted:
            if count_held(base) >= needed.get(base, 0):
                continue
            insts = [obj for (obj, n) in objs_here if obj == base]
            for inst in insts:
                full = f"{base} {inst}"
                if count_held(base) >= needed.get(base, 0):
                    break
                fb = step(f"take {full} from {rec}")
                if fb is None:
                    break

    # Phase 2: go to target and drop
    if target:
        go(target)
        look()
        # ensure we are at target by attempting to go by exact name
        if cur_loc and norm(cur_loc) != norm(target):
            # maybe target name mismatch; try without number?
            step(f"go to {target}")
        for base, num in wanted:
            while count_held(base) > 0:
                inst = free_held(base)
                if inst is None:
                    break
                fb = step(f"move {inst} to {target}")
                if fb is None:
                    break

    # Phase 3: if still missing, search again
    missing = False
    for base, num in wanted:
        if count_held(base) < needed.get(base, 0):
            missing = True
    if missing:
        for rec in initial_recs:
            if norm(rec) == norm(target):
                continue
