            look()
            for base, num in wanted:
                if count_held(base) >= needed.get(base, 0):
                    continue
                insts = [obj for (obj, n) in objs_here if obj == base]
                for inst in insts:
                    full = f"{base} {inst}"
                    if count_held(base) >= needed.get(base, 0):
                        break
                    fb = step(f"take {full} from {rec}")
                    if fb is None:
                        break
        if target:
